export const meta = {
  name: 'agents-md-workflow-audit',
  description: 'Multi-lens audit of the AGENTS.md development workflow and .claude/agents sub-agent definitions',
  phases: [
    { title: 'Analyze', detail: 'five independent lenses over AGENTS.md + sub-agents' },
    { title: 'Verify', detail: 'adversarially check each lens findings against real files' },
    { title: 'Synthesize', detail: 'merge into a ranked change list' },
  ],
}

const REPO = '/home/scottdensmore/Developer/scottdensmore/my-first-commit'

const COMMON = `
Repository root: ${REPO}
Key files you MUST read before concluding anything:
- AGENTS.md (the canonical agent instructions; "Development workflow (required)" steps 1-11 and the "Sub-agents" section)
- .claude/agents/ui-review.md, .claude/agents/code-review.md, .claude/agents/verifier.md, .claude/agents/entire-search.md
- package.json (scripts), .github/workflows/ci.yml, CONTRIBUTING.md, CLAUDE.md, GEMINI.md, .github/copilot-instructions.md
- docs/ (architecture.md, development.md, production.md, and anything else there)
- .codex/agents/ and .agents/ if they contain agent definitions
- scripts/check-agent-docs.mjs

This is a DOCUMENTATION + AGENT-CONFIG audit. Do not modify any files. Do not run the test suite,
builds, or playwright. Read-only analysis plus cheap commands (ls, git log, cat) only.

Quality bar: every finding must cite a concrete file:line and describe a concrete failure — a real
situation where an agent following these instructions does the wrong thing, stalls, wastes work, or
produces an inconsistent result. Do not report stylistic preferences, do not invent problems, and do
not pad. If a lens turns up nothing real, return an empty findings list. Prefer 2 sharp findings over
8 soft ones. For each finding propose the SPECIFIC replacement wording or config change.
`

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'short claim, <= 90 chars' },
          file: { type: 'string' },
          line: { type: 'string', description: 'line number or range' },
          severity: { type: 'string', enum: ['blocker', 'should-fix', 'nit'] },
          problem: { type: 'string', description: 'the defect and the concrete failure it causes' },
          fix: { type: 'string', description: 'specific replacement wording or config change' },
        },
        required: ['title', 'file', 'line', 'severity', 'problem', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          real: { type: 'boolean' },
          reason: { type: 'string' },
          correctedFix: { type: 'string', description: 'sharpened fix wording, or empty if unchanged' },
        },
        required: ['title', 'real', 'reason'],
      },
    },
  },
  required: ['verdicts'],
}

const LENSES = [
  {
    key: 'mechanics',
    prompt: `${COMMON}
LENS: workflow mechanics. Read steps 1-11 of the "Development workflow (required)" section as an
unattended agent that must execute them literally. Hunt for: ordering bugs, unreachable or circular
loop-backs (step 7 <-> 8 rerun rules), ambiguity about WHO runs WHAT (main agent vs verifier vs
code-review), missing termination conditions, steps that can be silently skipped, and instructions
that conflict with each other. Trace at least two concrete scenarios end to end (e.g. "code-review
finds a bug in a React component after verifier PASSed" and "a docs-only change") and report where
the instructions leave the agent guessing or force redundant full-gate runs.`,
  },
  {
    key: 'subagents',
    prompt: `${COMMON}
LENS: sub-agent correctness. This is the user's top priority. For EACH file in .claude/agents/:
check the YAML frontmatter (name matches filename, description is a good dispatch trigger, tools
list, model). Then check: do the granted tools actually permit everything the body instructs the
agent to do? Does the body's claimed scope match what AGENTS.md steps 6-8 say that agent does? Are
there contradictions between an agent's prompt and AGENTS.md (e.g. who runs focused unit tests, who
runs Playwright, whether the agent may edit files)? Is any agent missing that the workflow implies?
Does the AGENTS.md sub-agent table match the actual files (entire-search is present on disk but
absent from the table — decide whether that is correct)? Check whether verifier's instruction "do
not fix code" is enforced by its tool list, and whether code-review/ui-review can actually run the
git commands their prompts require. Also check .codex/agents and .agents for drift against
.claude/agents.`,
  },
  {
    key: 'drift',
    prompt: `${COMMON}
LENS: cross-document consistency. AGENTS.md claims to be canonical. Verify every factual claim in it
against reality: the Commands list vs package.json scripts (is any script missing or misdescribed?),
the "Full pre-PR validation" one-liner vs .github/workflows/ci.yml step order, the Layout section vs
the actual files on disk, the Gotchas vs the actual code in app/actions.ts and app/logger.ts, the
"More Detail" links vs files that exist in docs/, and CONTRIBUTING.md's validation list vs AGENTS.md
and CI. Report every mismatch with both sides quoted. Also verify scripts/check-agent-docs.mjs
actually enforces what AGENTS.md says it enforces.`,
  },
  {
    key: 'gaps',
    prompt: `${COMMON}
LENS: what is missing. The workflow covers inspect -> branch -> slice -> TDD -> diff -> ui-review ->
verifier -> code-review -> commit -> PR -> merge. Identify genuinely important gaps for an agent
working unattended in THIS repo, judged against what the repo already has (read docs/ and the
workflows in .github/ before claiming something is missing). Consider: handling CI failures after the
PR is opened, handling review comments from Copilot/humans, when to stop and ask the user, secret and
token handling during agent runs, treating GitHub issue/PR text and third-party content as untrusted
data, rollback, and what to do when the verifier reports a flake. Only report a gap if its absence
causes a real failure mode; explicitly say if the repo already covers it elsewhere and AGENTS.md just
needs a pointer.`,
  },
  {
    key: 'cost',
    prompt: `${COMMON}
LENS: proportionality and cost. The workflow mandates ui-review + verifier (full CI-equivalent gate
including playwright and a production build) + code-review before EVERY commit, plus reruns after any
finding. Assess whether this is proportionate, where it burns time or tokens for no signal, and where
it under-invests. Look for: full-gate reruns that could be scoped, sub-agent invocations that are
no-ops for certain change classes (docs-only, test-only), the rule barring the main agent from ever
running lint/format (is that practical?), and whether "concise reporting" instructions in the agents
are strong enough to keep command output out of the main context. Propose specific escape hatches
with precise trigger conditions, not vague advice.`,
  },
]

phase('Analyze')

const results = await pipeline(
  LENSES,
  (lens) => agent(lens.prompt, { label: `lens:${lens.key}`, phase: 'Analyze', schema: FINDINGS_SCHEMA }),
  (res, lens) => {
    if (!res || !res.findings || res.findings.length === 0) return { lens: lens.key, findings: [] }
    const list = res.findings
      .map((f, i) => `${i + 1}. [${f.severity}] ${f.title}\n   file: ${f.file}:${f.line}\n   problem: ${f.problem}\n   proposed fix: ${f.fix}`)
      .join('\n\n')
    return agent(
      `${COMMON}
You are an adversarial verifier. Another agent audited this repo through the "${lens.key}" lens and
produced the findings below. Your job is to REFUTE them. Open the cited files and read the actual
lines. Default to real=false when you cannot confirm the claim from the file contents. Mark real=false
if: the cited text does not say what the finding claims, the "problem" is a style preference rather
than a failure, the repo already handles it elsewhere, or the proposed fix would contradict another
part of AGENTS.md. When a finding survives but its fix is imprecise or would introduce a
contradiction, set correctedFix to sharper wording. Return one verdict per finding, same titles.

FINDINGS TO REFUTE:

${list}`,
      { label: `verify:${lens.key}`, phase: 'Verify', schema: VERDICT_SCHEMA },
    ).then((v) => ({
      lens: lens.key,
      findings: res.findings.map((f) => {
        const verdict = (v && v.verdicts || []).find((x) => x.title === f.title)
        return {
          ...f,
          real: verdict ? verdict.real : false,
          verifierReason: verdict ? verdict.reason : 'no verdict returned',
          fix: verdict && verdict.correctedFix ? verdict.correctedFix : f.fix,
        }
      }),
    }))
  },
)

const all = results.filter(Boolean).flatMap((r) => (r.findings || []).map((f) => ({ ...f, lens: r.lens })))
const confirmed = all.filter((f) => f.real)
log(`${all.length} raw findings, ${confirmed.length} survived adversarial verification`)

if (confirmed.length === 0) {
  return { confirmed: [], synthesis: 'No findings survived verification.' }
}

phase('Synthesize')

const synthesis = await agent(
  `${COMMON}
You are the synthesizer. Below are audit findings about AGENTS.md and the .claude/agents/*.md
sub-agent definitions that survived an adversarial verification pass. Produce the final
recommendation set for the repository owner.

Requirements:
- Merge duplicates across lenses. Drop anything that is really a restatement.
- Rank strictly by impact on an agent actually executing this workflow.
- Separate into: (A) AGENTS.md workflow changes, (B) sub-agent definition changes (per file), (C) optional/low priority.
- For each item give: the exact file, the current text (quoted), the proposed replacement text
  (ready to paste, matching the surrounding markdown style — note prettier ignores *.md so prose is
  hand-wrapped at ~100 cols), and one sentence on why it matters.
- Re-read the files yourself to make sure quoted "current text" is verbatim correct.
- Call out explicitly anything you think the auditors got WRONG or that the owner should reject.
- Be concise. This is a change list, not an essay.

FINDINGS:

${confirmed.map((f, i) => `${i + 1}. [${f.lens}/${f.severity}] ${f.title}\n   ${f.file}:${f.line}\n   problem: ${f.problem}\n   fix: ${f.fix}\n   verifier: ${f.verifierReason}`).join('\n\n')}`,
  { label: 'synthesize', phase: 'Synthesize' },
)

return { confirmedCount: confirmed.length, rawCount: all.length, confirmed, synthesis }

