2	// Keeps AGENTS.md the single source of agent instructions.
3	//
4	// CLAUDE.md, GEMINI.md, and .github/copilot-instructions.md must stay byte-for-byte pointers to
5	// AGENTS.md. Claude Code's `#` shortcut appends learnings to CLAUDE.md, which is exactly the drift
6	// this guards against: the check fails, and the content moves to AGENTS.md instead.
7	//
8	// Usage:
9	//   node scripts/check-agent-docs.mjs          verify (exit 1 on drift)
10	//   node scripts/check-agent-docs.mjs --fix    rewrite the pointer files from the template
11	
12	import { readFile, writeFile } from "node:fs/promises";
13	import { dirname, join } from "node:path";
14	import { fileURLToPath } from "node:url";
15	
16	const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
17	const CANONICAL_DOC = "AGENTS.md";
18	const MIN_CANONICAL_LINES = 20;
19	const WRAP_COLUMNS = 100;
20	
21	const POINTER_DOCS = [
22	  {
23	    file: "CLAUDE.md",
24	    title: "Claude Code",
25	    link: "AGENTS.md",
26	    note: "Anything captured with the `#` shortcut during a session belongs in",
27	  },
28	  {
29	    file: "GEMINI.md",
30	    title: "Gemini CLI",
31	    link: "AGENTS.md",
32	    note: "Anything worth remembering belongs in",
33	  },
34	  {
35	    file: ".github/copilot-instructions.md",
36	    title: "GitHub Copilot",
37	    link: "../AGENTS.md",
38	    note: "Anything worth remembering belongs in",
39	  },
40	];
41	
42	function wrap(text, width) {
43	  const lines = [];
44	  let current = "";
45	
46	  for (const word of text.split(" ")) {
47	    if (current === "") {
48	      current = word;
49	    } else if (`${current} ${word}`.length <= width) {
50	      current = `${current} ${word}`;
51	    } else {
52	      lines.push(current);
53	      current = word;
54	    }
55	  }
56	
57	  if (current !== "") lines.push(current);
58	  return lines.join("\n");
59	}
60	
61	function expectedContent({ title, link, note }) {
62	  const paragraphs = [
63	    `# ${title}`,
64	    `Project instructions for this repository live in one canonical file: [${CANONICAL_DOC}](${link}).`,
65	    `Read [${CANONICAL_DOC}](${link}) for commands, layout, gotchas, and conventions.`,
66	    `Do not add project instructions to this file. ${note} [${CANONICAL_DOC}](${link}) instead. ` +
67	      "CI runs `npm run check:agent-docs`, which fails if this file drifts from the pointer template.",
68	  ];
69	
70	  return `${paragraphs.map((paragraph) => wrap(paragraph, WRAP_COLUMNS)).join("\n\n")}\n`;
71	}
72	
73	async function readIfPresent(path) {
74	  try {
75	    return await readFile(path, "utf8");
76	  } catch (error) {
77	    if (error.code === "ENOENT") return null;
78	    throw error;
79	  }
80	}
81	
82	function firstDifference(actual, expected) {
83	  const actualLines = actual.split("\n");
84	  const expectedLines = expected.split("\n");
85	
86	  for (let index = 0; index < Math.max(actualLines.length, expectedLines.length); index += 1) {
87	    if (actualLines[index] !== expectedLines[index]) {
88	      return {
89	        line: index + 1,
90	        actual: actualLines[index] ?? "<end of file>",
91	        expected: expectedLines[index] ?? "<end of file>",
92	      };
93	    }
94	  }
95	
96	  return null;
97	}
98	
99	async function main() {
100	  const fix = process.argv.includes("--fix");
101	  const problems = [];
102	
103	  const canonical = await readIfPresent(join(repoRoot, CANONICAL_DOC));
104	  if (canonical === null) {
105	    problems.push(`${CANONICAL_DOC} is missing. It holds the canonical agent instructions.`);
106	  } else if (canonical.trim().split("\n").length < MIN_CANONICAL_LINES) {
107	    problems.push(
108	      `${CANONICAL_DOC} looks empty or stubbed out. Agent instructions belong there, not in the ` +
109	        "pointer files.",
110	    );
111	  }
112	
113	  for (const doc of POINTER_DOCS) {
114	    const path = join(repoRoot, doc.file);
115	    const expected = expectedContent(doc);
116	    const actual = await readIfPresent(path);
117	
118	    if (actual === expected) continue;
119	
120	    if (fix) {
121	      await writeFile(path, expected, "utf8");
122	      console.log(`fixed ${doc.file}`);
123	      continue;
124	    }
125	
126	    if (actual === null) {
127	      problems.push(`${doc.file} is missing.`);
128	      continue;
129	    }
130	
131	    const difference = firstDifference(actual, expected);
132	    problems.push(
133	      `${doc.file} has drifted from the pointer template at line ${difference.line}.\n` +
134	        `    expected: ${difference.expected}\n` +
135	        `    actual:   ${difference.actual}`,
136	    );
137	  }
138	
139	  if (fix) {
140	    if (problems.length > 0) {
141	      console.error(problems.join("\n\n"));
142	      process.exit(1);
143	    }
144	    console.log("Agent docs are consistent.");
145	    return;
146	  }
147	
148	  if (problems.length > 0) {
149	    console.error("Agent instruction files are out of sync:\n");
150	    console.error(`${problems.join("\n\n")}\n`);
151	    console.error(
152	      `Move any real instructions into ${CANONICAL_DOC}, then run ` +
153	        "`npm run check:agent-docs -- --fix` to restore the pointer files.",
154	    );
155	    process.exit(1);
156	  }
157	
158	  console.log("Agent docs are consistent.");
159	}
160	
161	await main();
